         } catch (_: Exception) {
             try {
                 val list = supabase.from("tester_reports").select {
                     filter {
                         eq("campaign_id", campaignId)
                         eq("user_id", uid)
                     }
                     order("created_at", Order.DESCENDING)
                     limit(10)
                 }.decodeList<TesterReport>()
                 if (missionId != null) {
                     list.firstOrNull { it.isCreatedToday() && it.missionId == missionId }
                 } else {
