         val memberProgress = detail.testers.map { tester ->
             MemberProgress(
                 member = CampaignMember(campaignId = campaignId, userId = tester.userId, joinedAt = tester.joinedAt),
                 profile = detail.profiles[tester.userId],
                 days = tester.days,
             )
